    "original": "شَهِدَ النِّصْفُ الثَّانِي مِنَ القَرْنِ التَّاسِعَ عَشَرَ المِيلَادِيِّ تَحَوُّلًا كَبِيرًا فِي رِحْلَةِ الحَجِّ لِأَهْلِ إِنْدُونِيسِيَا (أَهْلِ جَاوَى)، حَيْثُ أَدَّى افْتِتَاحُ قَنَاةِ السُّوَيْسِ عَامَ 1869م وَدُخُولُ السُّفُنِ البُخَارِيَّةِ إِلَى اخْتِصَارِ زَمَنِ السَّفَرِ مِنْ عِدَّةِ أَشْهُرٍ إِلَى عِدَّةِ أَسَابِيعَ، مِمَّا زَادَ مِنْ أَعْدَادِ الحُجَّاجِ وَعَمَّقَ التَّوَاصُلَ العِلْمِيَّ مَعَ عُلَمَاءِ الحَرَمَيْنِ الشَّرِيفَيْنِ.",
